/**
 * 契约测试模板（test-runner.contract 自动生成示例）
 *
 * 本文件由 test-runner.contract 从 contracts/openapi.yaml 自动生成。
 * 每个 operationId 对应一个 describe 块，每个 describe 包含 3-5 个 it 用例。
 *
 * 设计原则：
 * 1. 每个端点至少覆盖：happy path + validation error + auth + rate limit + 边界
 * 2. 使用 toMatchSchema 校验响应 schema（自动从 openapi.yaml 推导）
 * 3. traceId 必出现在所有响应中（RFC 9457 合规）
 * 4. Idempotency-Key 在 mutating endpoints 自动使用
 *
 * @generated by project-orchestrator-bundle / test-runner
 * @date 2026-08-24
 * @openapi contracts/openapi.yaml
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import Ajv from 'ajv';
import addFormats from 'ajv-formats';
import { readFileSync } from 'fs';
import { resolve } from 'path';

// ============================================================
// 全局设置：加载 OpenAPI + 初始化 AJV
// ============================================================

const openapiPath = resolve(__dirname, '../../contracts/openapi.yaml');
let openapi: any;
let ajv: Ajv;

beforeAll(() => {
  openapi = YAML.load(readFileSync(openapiPath, 'utf-8'));
  ajv = addFormats(new Ajv({ strict: false, allErrors: true }));
});

// 辅助函数：从 openapi 路径读取 schema
const getSchema = (ref: string) => {
  const path = ref.replace('#/components/schemas/', '').split('/');
  let schema: any = openapi.components.schemas;
  for (const p of path) schema = schema[p];
  return schema;
};

// 辅助函数：从 openapi 路径读取 response
const getResponse = (ref: string) => {
  const path = ref.replace('#/components/responses/', '').split('/');
  let resp: any = openapi.components.responses;
  for (const p of path) resp = resp[p];
  return resp;
};

// 校验响应 schema
const validateSchema = (data: any, schema: any) => {
  const validate = ajv.compile(schema);
  const valid = validate(data);
  if (!valid) {
    throw new Error(`Schema validation failed: ${JSON.stringify(validate.errors, null, 2)}`);
  }
  return true;
};

// 校验 Problem schema（错误响应）
const validateProblem = (data: any) => {
  validateSchema(data, getSchema('Problem'));
  expect(data).toHaveProperty('traceId');
  expect(data.traceId).toBeTruthy();
};

// 测试客户端（mock fetch）
const apiClient = {
  baseURL: process.env.API_BASE || 'http://localhost:8080/v1',

  async request(path: string, options: any = {}) {
    const url = `${this.baseURL}${path}`;
    const res = await fetch(url, {
      method: options.method || 'GET',
      headers: {
        'Content-Type': 'application/json',
        ...(options.token && { Authorization: `Bearer ${options.token}` }),
        ...(options.headers || {}),
      },
      body: options.body ? JSON.stringify(options.body) : undefined,
    });
    const data = res.status === 204 ? null : await res.json().catch(() => null);
    return { status: res.status, headers: res.headers, data };
  },
};

// ============================================================
// 1. POST /auth/login
// ============================================================
describe('POST /auth/login (openapi.yaml:paths./auth/login)', () => {
  it('should return:  200 + token + user on valid credentials', async () => {
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      body: { email: 'user@example.com', password: 'Password123', code: '123456' },
    });

    expect(res.status).toBe(200);
    expect(res.data).toHaveProperty('token');
    expect(res.data).toHaveProperty('user');
    validateSchema(res.data, getSchema('LoginResponse'));
  });

  it('should return:  400 on missing required fields', async () => {
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      body: { email: 'user@example.com' }, // missing password
    });

    expect(res.status).toBe(400);
    validateProblem(res.data);
    expect(res.data.code).toMatch(/^U1/); // 参数校验类错误
  });

  it('should return:  401 on invalid credentials', async () => {
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      body: { email: 'user@example.com', password: 'wrong-password' },
    });

    expect(res.status).toBe(401);
    validateProblem(res.data);
    expect(res.data.code).toBe('U1001'); // 凭据无效
  });

  it('should return:  422 on validation business rule violation', async () => {
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      body: { email: 'locked@example.com', password: 'Password123' },
    });

    expect(res.status).toBe(422);
    validateProblem(res.data);
    expect(res.data.code).toMatch(/^U2/); // 业务校验类
  });

  it('should return:  429 after 5 failed attempts within 10 minutes', async () => {
    // 5 次失败尝试
    for (let i = 0; i < 5; i++) {
      await apiClient.request('/auth/login', {
        method: 'POST',
        body: { email: 'user@example.com', password: 'wrong' },
      });
    }

    // 第 6 次应该被限流
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      body: { email: 'user@example.com', password: 'Password123' },
    });

    expect(res.status).toBe(429);
    expect(res.headers.get('retry-after')).toBeDefined();
    validateProblem(res.data);
  });

  it('should return:  500 on internal server error', async () => {
    // 模拟服务端崩溃（通过特殊 token 触发）
    const res = await apiClient.request('/auth/login', {
      method: 'POST',
      headers: { 'X-Test-Scenario': 'db-down' },
      body: { email: 'user@example.com', password: 'Password123' },
    });

    expect(res.status).toBe(500);
    validateProblem(res.data);
    expect(res.data.category).toBe('SYSTEM_ERROR');
    expect(res.data.traceId).toBeTruthy();
  });
});

