describe('POST /uploads (openapi.yaml:paths./uploads)', () => {
  it('should return:  201 + UploadResult with URL', async () => {
    const formData = new FormData();
    const blob = new Blob(['fake-image-bytes'], { type: 'image/png' });
    formData.append('file', blob, 'avatar.png');
    formData.append('category', 'avatar');

    const res = await fetch(`${apiClient.baseURL}/uploads`, {
      method: 'POST',
      headers: { Authorization: 'Bearer valid_jwt' },
      body: formData,
    });

    expect(res.status).toBe(201);
    const data = await res.json();
    expect(data).toHaveProperty('id');
    expect(data).toHaveProperty('url');
    expect(data.url).toMatch(/^https:\/\//);
  });

  it('should return:  400 when file is missing', async () => {
    const formData = new FormData();
    formData.append('category', 'avatar');

    const res = await fetch(`${apiClient.baseURL}/uploads`, {
      method: 'POST',
      headers: { Authorization: 'Bearer valid_jwt' },
      body: formData,
    });

    expect(res.status).toBe(400);
  });

  it('should return:  413 when file exceeds size limit', async () => {
    // 创建超大文件（mock）
    const formData = new FormData();
    const bigBlob = new Blob([new ArrayBuffer(20 * 1024 * 1024)], { type: 'image/png' });
    formData.append('file', bigBlob, 'huge.png');
    formData.append('category', 'avatar');

    const res = await fetch(`${apiClient.baseURL}/uploads`, {
      method: 'POST',
      headers: { Authorization: 'Bearer valid_jwt' },
      body: formData,
    });

    expect(res.status).toBe(413);
  });
});

